"""Установщик системы дорожных карт — один файл.

Сгенерирован make_dist.py из План_СистемаДорожныхКарт_v18.md. Не редактировать вручную:
при изменении плана пересобрать (python make_dist.py).

Развёртывание = 2 файла: этот установщик + план.

Использование:
    python roadmap_setup.py --root "<WORKSPACE>\ДорожнаяКарта" [--project ProjectA] [--force]

Создаёт структуру, скрипты, конфиги и запускает первичную генерацию.
"""
import argparse
import base64
import json
import pathlib
import subprocess
import sys
import datetime

PLAN_VERSION = "v18"

# SHA-256 обезличенных блоков кода из плана (проверка A33)
MANIFEST = {
    "new_task.py": "5b75e1c20da1b72d8338ddd2737aebf1ccf4fe365b3c62067dbfd3e9220d60e3",
    "sync_roadmap.py": "1f5322896f7cb8428c22d081932c25b260386c08734c4914b3559afa20ce309d",
    "validate_roadmap.py": "ec5fc0476b5840f9f208e5d8edd37afc71efb3768c4b73257b3caac5d9012571",
    "check_plan.py": "366f0f40958e237aef2b59b82262b041409b10f0d981382bd9a02ed8e4bda16d"
}

SCRIPTS = {
    "new_task.py": "",
    "sync_roadmap.py": "",
    "validate_roadmap.py": "",
    "check_plan.py": ""
}


def decode_scripts():
    return {name: base64.b64decode(data).decode("utf-8") for name, data in SCRIPTS.items()}


def write_scripts(root):
    for name, code in decode_scripts().items():
        code = code.replace("__ROOT__", str(root))
        (root / name).write_text(code, encoding="utf-8")
        print(f"  OK {name}")


def write_configs(root, project):
    today = datetime.date.today().isoformat()
    projects_file = root / "projects.json"
    if projects_file.exists():
        print("  SKIP projects.json (существует)")
    else:
        projects_file.write_text(json.dumps({
            "version": 1,
            "defaultProject": project,
            "activeProject": project,
            "projects": [{
                "id": 1,
                "name": project,
                "fullName": f"1. {project}",
                "path": str(root.parent / project),
                "roadmapDir": f"1-{project}",
                "roadmapFile": f"1-{project}/ДорожнаяКарта.md",
                "commands": [f"проект {project}", "проект 1"],
            }],
        }, ensure_ascii=False, indent=2), encoding="utf-8")
        print("  OK projects.json")

    registry = root / "id_registry.json"
    if registry.exists():
        print("  SKIP id_registry.json (существует)")
    else:
        registry.write_text(json.dumps({"version": 1, "nextId": 1, "allocations": []},
                                       ensure_ascii=False, indent=2), encoding="utf-8")
        print("  OK id_registry.json")

    roadmap_dir = root / f"1-{project}"
    roadmap_dir.mkdir(parents=True, exist_ok=True)
    (root / "отчеты").mkdir(exist_ok=True)
    tasks_file = roadmap_dir / "tasks.json"
    if tasks_file.exists():
        print("  SKIP tasks.json (существует)")
    else:
        tasks_file.write_text(json.dumps({"created": today, "updated": today, "tasks": []},
                                         ensure_ascii=False, indent=2), encoding="utf-8")
        print("  OK tasks.json")


def main():
    ap = argparse.ArgumentParser(description="Установщик системы дорожных карт (один файл)")
    ap.add_argument("--root", required=True, help="Путь к папке ДорожнаяКарта (создаётся при отсутствии)")
    ap.add_argument("--project", default="ProjectA", help="Имя первого проекта")
    ap.add_argument("--force", action="store_true", help="Перезаписать существующие скрипты")
    ap.add_argument("--plan", help="Файл плана (копируется в целевую папку)")
    args = ap.parse_args()

    root = pathlib.Path(args.root).resolve()
    root.mkdir(parents=True, exist_ok=True)

    print(f"Установка в {root} ({PLAN_VERSION})")
    if (root / "projects.json").exists() and not args.force:
        print("ERROR: система уже установлена (projects.json существует). Используйте --force")
        return 1

    write_scripts(root)
    write_configs(root, args.project)
    if args.plan:
        src = pathlib.Path(args.plan)
        if src.exists():
            (root / src.name).write_text(src.read_text(encoding="utf-8"), encoding="utf-8")
            print(f"  OK {src.name}")

    for script in ("validate_roadmap.py", "sync_roadmap.py"):
        result = subprocess.run([sys.executable, str(root / script)], cwd=str(root))
        if result.returncode != 0:
            print(f"ERROR: {script} завершился с кодом {result.returncode}")
            return result.returncode

    print("ГОТОВО. Проверка: python validate_roadmap.py; аудит плана: python check_plan.py")
    return 0


if __name__ == "__main__":
    sys.exit(main())
